Value.Value:
v2((data, context) => {
  // Get the current value of SettingsTag
  let settingsTag = data.SettingsTag || "N/A"; 

  // Generate the Description field dynamically based on available values
  return `${settingsTag} - ${data.ViewType || "N/A"}; Heading: ${data.HeadingType || "N/A"} / ${data.HeadingSize || "N/A"}; Kicker: ${data.KickerSize || "N/A"}; Align: ${data.TextAlign || "N/A"}; Reverse: ${data.ReverseOrder ? "Yes" : "No"}; Aspect: ${data.ImageAspectRatio || "N/A"}`;
});

v2((data, context) => {
  // Generate the Description field dynamically
  return `${data.SettingsTag || "N/A"} - ${data.ViewType || "N/A"}; Main: ${data.ContainerType || "N/A"} / ${data.TextColor || "N/A"} / ${data.BgColor || "N/A"}; Layout: ${data.AlternatePositions ? "Alternate" : "No Alternate"} / ${data.ColLayout || "N/A"} / ${data.UseImageOverlay ? "ImageOverlay" : "No ImageOverlay"} / ${data.AdvancedViewType || "N/A"}`;
});
